mapper.select:
select sport.id,time,image, title,motion,l.k league,l.text leagueDescribe
    from sport left join league l on l.id = sport.league_id

     title like concat('%',#{title},'%') 
     and league_id=#{leagueId}
    and time between #{startTime} and #{endTime}

order by time

select sport.id,sport.text,video,time,title,cal,motion,l.k league,l.text leagueDescribe
from sport left join league l on l.id = sport.league_id
where sport.id=#{id}
